from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
a=s.index(' if(raw==="zero_one"){')
b=s.index(' if(raw==="numbers_1000"){',a)
s=s[:a]+" if(raw===\"zero_one\"){\n  const live=stageOverride===null&&blockSession?.kind===\"g3quiz\"&&blockSession.key===\"g3:zero_one\";\n  return g3ZeroOneQuestion(d,live?blockSession.done:null);\n }\n"+s[b:]
anchor='function g3UnitNumberQuestion('
assert s.count(anchor)==1
s=s.replace(anchor,"const G3_ZERO_ONE_VARIANTS=[\n [\"mulOneR\",\"mulOneL\",\"mulZeroR\",\"mulZeroL\"],\n [\"divOne\",\"selfDiv\",\"zeroDiv\",\"check\"],\n [\"oneSum\",\"zeroBrackets\",\"twoRule\",\"missing\"]\n];\nfunction g3ZeroOneQuestion(stage,slot=null){\n const d=Math.max(0,Math.min(2,Number(stage)||0)),variants=G3_ZERO_ONE_VARIANTS[d];\n const v=slot===null?g6RandomFrom(variants):variants[((slot%variants.length)+variants.length)%variants.length];\n const sig=(key)=>\"g3:zero_one:\"+d+\":\"+v+\":\"+key;\n const number=(text,answer,ex,key,extra={})=>g6NumberInputQuestion(text,answer,ex,sig(key),\n  {inputHint:\"Введи целое число.\",audit:{type:\"g3ZeroOne\",variant:v,...extra,answer:rational(answer,1)}});\n if(d===0){\n  const a=ri(2,150),one=v===\"mulOneR\"||v===\"mulOneL\",left=v===\"mulOneL\"||v===\"mulZeroL\";\n  const other=one?1:0,answer=one?a:0;\n  const text=\"<b>\"+(left?other:a)+\" · \"+(left?a:other)+\"</b> = ?\";\n  const ex=one?\"При умножении на 1 число не меняется: <b>\"+answer+\"</b>.\":\n   \"При умножении на 0 получается <b>0</b>.\";\n  return number(text,answer,ex,a,{a,other,left});\n }\n if(d===1){\n  const a=ri(2,500);\n  if(v===\"divOne\")return number(\"<b>\"+a+\" : 1</b> = ?\",a,a+\" : 1 = <b>\"+a+\"</b>.\",a,{a,divisor:1});\n  if(v===\"selfDiv\")return number(\"<b>\"+a+\" : \"+a+\"</b> = ?\",1,\"Любое ненулевое число, делённое само на себя, равно <b>1</b>.\",a,{a,divisor:a});\n  if(v===\"zeroDiv\")return number(\"<b>0 : \"+a+\"</b> = ?\",0,\"0 : \"+a+\" = <b>0</b>, так как \"+a+\" · 0 = 0.\",a,{a,divisor:a});\n  const kind=ri(0,2),right=ri(0,1)===0,expected=kind===0?0:a,shown=right?expected:expected+ri(1,3);\n  const expression=kind===0?a+\" · 0\":kind===1?a+\" : 1\":\"0 : \"+a;\n  const correct=right?\"Верно\":\"Неверно\";\n  return g6ChoiceQuestion(\"Верно ли равенство <b>\"+expression+\" = \"+shown+\"</b>?\",\n   correct,[\"Верно\",\"Неверно\"],expression+\" = <b>\"+expected+\"</b>.\",\n   sig(a+\":\"+kind+\":\"+shown),{type:\"g3ZeroOne\",variant:v,a,kind,shown,expected,right,answer:correct});\n }\n const a=ri(30,300),b=ri(10,90),c=ri(5,90);\n if(v===\"oneSum\"){\n  return number(\"<b>\"+a+\" · 1 + \"+b+\" · 1</b> = ?\",a+b,\n   a+\" · 1 = \"+a+\"; \"+b+\" · 1 = \"+b+\".<br>\"+a+\" + \"+b+\" = <b>\"+(a+b)+\"</b>.\",\n   a+\":\"+b,{a,b});\n }\n if(v===\"zeroBrackets\"){\n  return number(\"<b>(\"+a+\" + \"+b+\") · 0 + \"+c+\"</b> = ?\",c,\n   \"Сначала \"+a+\" + \"+b+\" = \"+(a+b)+\".<br>\"+(a+b)+\" · 0 = 0; 0 + \"+c+\" = <b>\"+c+\"</b>.\",\n   a+\":\"+b+\":\"+c,{a,b,c});\n }\n if(v===\"twoRule\"){\n  return number(\"<b>\"+a+\" : \"+a+\" + \"+b+\" · 1</b> = ?\",1+b,\n   a+\" : \"+a+\" = 1; \"+b+\" · 1 = \"+b+\".<br>1 + \"+b+\" = <b>\"+(1+b)+\"</b>.\",\n   a+\":\"+b,{a,b});\n }\n return number(\"Найди неизвестное число: <b>□ : 1 − \"+b+\" = \"+a+\"</b>\",a+b,\n  \"Если □ : 1 = □, то □ − \"+b+\" = \"+a+\".<br>Значит □ = \"+a+\" + \"+b+\" = <b>\"+(a+b)+\"</b>.\",\n  a+\":\"+b,{a,b});\n}\n\n"+anchor)
assert s.count('function g3ZeroOneQuestion(')==1
p.write_text(s,encoding='utf-8')
print('zero/one patch applied:',len(s))
